// ═══ BEFORE: manual containsKey + put (2 operations, race-prone) ═══
if (!map.containsKey("SAV2001")) {
    map.put("SAV2001", new ArrayList<>());
}
map.get("SAV2001").add(trade);
// In ConcurrentHashMap: another thread can put() between containsKey and put!

// ═══ AFTER: computeIfAbsent (1 atomic operation) ═══
map.computeIfAbsent("SAV2001", k -> new ArrayList<>()).add(trade);
// If absent: creates list, puts it, returns it. If present: returns existing.
// ATOMIC in ConcurrentHashMap!

// ═══ merge: counting / accumulating ═══
// BEFORE: if (map.containsKey(key)) map.put(key, map.get(key) + 1); else map.put(key, 1);
// AFTER:
map.merge("SAV2001", 1, Integer::sum);
// Absent → put 1. Present → old + 1. ONE operation!

// ═══ putIfAbsent: insert only if missing ═══
map.putIfAbsent("SAV2001", "Rajesh");  // only if key not present
// Returns: existing value (if present), null (if inserted)

// ═══ getOrDefault: no null check ═══
int count = map.getOrDefault("SAV2001", 0);  // 0 if key absent
// No need for: map.containsKey("SAV2001") ? map.get("SAV2001") : 0

// ═══ compute: always recompute ═══
map.compute("SAV2001", (k, v) -> v == null ? 1 : v + 1);
// Runs function regardless of presence. null result → remove key.
