package com.bank.mapops;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class MapOperationsTest {

    @Test
    void computeIfAbsent_grouping() {
        Map<String, List<String>> accountTrades = new HashMap<>();
        accountTrades.computeIfAbsent("SAV2001", k -> new ArrayList<>()).add("TRD-001");
        accountTrades.computeIfAbsent("SAV2001", k -> new ArrayList<>()).add("TRD-002");
        accountTrades.computeIfAbsent("CUR3001", k -> new ArrayList<>()).add("TRD-003");

        assertThat(accountTrades.get("SAV2001")).containsExactly("TRD-001", "TRD-002");
        assertThat(accountTrades.get("CUR3001")).containsExactly("TRD-003");
    }

    @Test
    void merge_counting() {
        Map<String, Integer> txnCounts = new HashMap<>();
        txnCounts.merge("SAV2001", 1, Integer::sum);  // 1
        txnCounts.merge("SAV2001", 1, Integer::sum);  // 2
        txnCounts.merge("SAV2001", 1, Integer::sum);  // 3
        txnCounts.merge("CUR3001", 1, Integer::sum);  // 1
        assertThat(txnCounts.get("SAV2001")).isEqualTo(3);
        assertThat(txnCounts.get("CUR3001")).isEqualTo(1);
    }

    @Test
    void putIfAbsent_doesNotOverwrite() {
        Map<String, String> map = new HashMap<>();
        map.putIfAbsent("SAV2001", "Rajesh");
        map.putIfAbsent("SAV2001", "Priya");  // NOT overwritten!
        assertThat(map.get("SAV2001")).isEqualTo("Rajesh");
    }

    @Test
    void getOrDefault_noNullCheck() {
        Map<String, Integer> map = Map.of("SAV2001", 5);
        assertThat(map.getOrDefault("SAV2001", 0)).isEqualTo(5);
        assertThat(map.getOrDefault("MISSING", 0)).isEqualTo(0);  // default!
    }
}
