class TradeAggregator {
    Map<String, List<Trade>> byAccount = new ConcurrentHashMap<>();
    Map<String, Integer>     txnCount  = new ConcurrentHashMap<>();
    Map<String, BigDecimal>  totalVol  = new ConcurrentHashMap<>();

    void record(Trade t) {
        // lazy init list, then add  — one atomic call
        byAccount.computeIfAbsent(t.account(), k -> new ArrayList<>())
                 .add(t);
        // count per account
        txnCount.merge(t.account(), 1, Integer::sum);
        // accumulate volume
        totalVol.merge(t.account(), t.amount(), BigDecimal::add);
    }
    int countFor(String acct) {
        return txnCount.getOrDefault(acct, 0);   // null-safe read
    }
    void registerOnce(String acct, Summary s) {
        txnSummaries.putIfAbsent(acct, s);        // insert-if-missing
    }
}
